(function($){"use strict";const CONFIG={debounceDelay:300,debug:window.gstoreMiniCart?.debug||false};let lastAddToCartAt=0;let lastUserActionAt=0;let badgeObserver=null;let observerPaused=false;const CART_COUNT_KEY="gstore_cart_count";const CART_COUNT_TS_KEY="gstore_cart_count_ts";function saveCartCount(count){try{localStorage.setItem(CART_COUNT_KEY,String(count));localStorage.setItem(CART_COUNT_TS_KEY,String(Date.now()))}catch(e){}}function getSavedCartCount(){try{var count=parseInt(localStorage.getItem(CART_COUNT_KEY)||"0",10);var ts=parseInt(localStorage.getItem(CART_COUNT_TS_KEY)||"0",10);if(Date.now()-ts>30*60*1e3)return null;return Number.isNaN(count)?null:count}catch(e){return null}}function debugLog(...args){if(CONFIG.debug&&window.console&&console.log){console.log("[MiniCart]",...args)}}function getNonce(){return window.wc?.storeApiNonce||window.gstoreMiniCart?.storeApiNonce||null}function getCurrentCountFromDom(){const counterEl=document.querySelector(".Gstore-cart-count")||document.querySelector(".wc-block-mini-cart__badge");if(!counterEl)return null;const value=parseInt(counterEl.textContent||"0",10);return Number.isNaN(value)?null:value}function getCountFromFragments(fragments){if(!fragments)return null;const fragmentHtml=fragments[".Gstore-cart-count"]||fragments[".wc-block-mini-cart__badge"]||null;if(!fragmentHtml)return null;const wrapper=document.createElement("div");wrapper.innerHTML=fragmentHtml;const text=wrapper.textContent||"";const value=parseInt(text,10);return Number.isNaN(value)?null:value}function syncDOM(count){observerPaused=true;const badges=document.querySelectorAll(".wc-block-mini-cart__badge");badges.forEach(badge=>{badge.textContent=count.toString();const ariaLabel=badge.getAttribute("aria-label");if(ariaLabel){badge.setAttribute("aria-label",ariaLabel.replace(/\d+/,count.toString()))}});const customCounters=document.querySelectorAll(".Gstore-cart-count");customCounters.forEach(counter=>{counter.textContent=count.toString();const ariaLabel=counter.getAttribute("aria-label");if(ariaLabel){counter.setAttribute("aria-label",ariaLabel.replace(/\d+/,count.toString()))}});saveCartCount(count);setTimeout(function(){observerPaused=false},100)}function startBadgeProtection(){if(badgeObserver)return;var savedCount=getSavedCartCount();if(savedCount===null||savedCount<=0)return;var targets=[];var miniCartWrapper=document.querySelector(".wc-block-mini-cart");if(miniCartWrapper)targets.push(miniCartWrapper);document.querySelectorAll(".Gstore-cart-count, .wc-block-mini-cart__badge").forEach(function(el){targets.push(el)});var header=document.querySelector("header")||document.querySelector(".site-header")||document.querySelector("#masthead");if(header)targets.push(header);if(targets.length===0)return;badgeObserver=new MutationObserver(function(mutations){if(observerPaused)return;var currentSaved=getSavedCartCount();if(currentSaved===null||currentSaved<=0)return;var currentDom=getCurrentCountFromDom();if((currentDom===0||currentDom===null)&&currentSaved>0){syncDOM(currentSaved)}});var observerConfig={childList:true,subtree:true,characterData:true};targets.forEach(function(target){try{badgeObserver.observe(target,observerConfig)}catch(e){}});debugLog("Badge protection ativa para",targets.length,"alvos")}function handleAddedToCart(event,fragments,cart_hash){debugLog("Produto adicionado ao carrinho");lastAddToCartAt=Date.now();lastUserActionAt=Date.now();const fragmentCount=getCountFromFragments(fragments);if(fragmentCount!==null){syncDOM(fragmentCount)}if(badgeObserver){badgeObserver.disconnect();badgeObserver=null}setTimeout(startBadgeProtection,500)}function handleRemovedFromCart(event,fragments,cart_hash){debugLog("Produto removido do carrinho");lastUserActionAt=Date.now();var fragmentCount=getCountFromFragments(fragments);if(fragmentCount!==null){syncDOM(fragmentCount)}if(badgeObserver){badgeObserver.disconnect();badgeObserver=null}setTimeout(startBadgeProtection,500)}function handleFragmentsRefreshed(){debugLog("Fragmentos atualizados");var domCount=getCurrentCountFromDom();var savedCount=getSavedCartCount();if((domCount===0||domCount===null)&&savedCount!==null&&savedCount>0){syncDOM(savedCount)}}function initEventListeners(){$(document.body).on("added_to_cart",handleAddedToCart);$(document.body).on("removed_from_cart",handleRemovedFromCart);$(document.body).on("wc_fragments_refreshed",handleFragmentsRefreshed);$(document.body).on("updated_wc_div",function(){if(document.body.classList.contains("woocommerce-cart")){lastUserActionAt=Date.now();var domCount=getCurrentCountFromDom();if(domCount!==null)saveCartCount(domCount)}});$(document.body).on("wc_cart_emptied",function(){lastUserActionAt=Date.now();syncDOM(0);if(badgeObserver){badgeObserver.disconnect();badgeObserver=null}})}function init(){debugLog("Inicializando Mini Cart Sync v3...");initEventListeners();var domCount=getCurrentCountFromDom();var savedCount=getSavedCartCount();var phpCount=typeof window.gstore_wc?.cart_count==="number"?window.gstore_wc.cart_count:null;if(typeof phpCount==="number"&&phpCount>0){if(domCount!==phpCount){syncDOM(phpCount)}saveCartCount(phpCount)}else if(savedCount!==null&&savedCount>0&&(domCount===0||domCount===null)){syncDOM(savedCount)}setTimeout(startBadgeProtection,300);debugLog("Mini Cart Sync v3 inicializado")}if(typeof jQuery!=="undefined"&&jQuery.ready){jQuery(document).ready(init)}else if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}window.gstoreRefreshMiniCart=function(){debugLog("refreshMiniCart desabilitado para proteger sessão")}})(jQuery);
